/**
 * @file helm_shell.h
 * @brief 主界面翻页：待机 / 概览 / 心率 / 速度 / 地图 / 转向 / 爬升。
 */

#ifndef HELM_SHELL_H
#define HELM_SHELL_H

#include "live_map/map_page.h"

#ifdef __cplusplus
extern "C" {
#endif

void helm_shell_attach(map_page_t * map);
void helm_shell_bind_keys(void);
void helm_shell_refresh(void);
/** @brief 地图重绘后把底栏/导航条提到画布前面。 */
void helm_shell_raise_chrome(void);
/** @brief 主界面入场动效：时钟块/状态列/操作条错峰淡入。
 *  触发点两处（互斥）：页面出现（map_will_appear）与主题重建末尾（重建会换控件）。 */
void helm_shell_enter_anim(void);
/** @brief 被菜单等盖住：停仪表绘制/搜星动画，数据仍由 map_page 接收。 */
void helm_shell_pause_for_cover(void);
/** @brief 回到前台：先恢复数字，搜星页顶部折线延到转场后再画。 */
void helm_shell_resume_after_cover(void);
/** @brief 自动暂停节拍：菜单盖住时仍可恢复/暂停记录，暂停条回主界面再收。 */
void helm_shell_autopause_tick(void);
void helm_shell_set_paused(bool paused);
bool helm_shell_paused(void);
void helm_shell_toggle_ride(void);
/** @brief 续录：接上旧里程/计时，并画出旧轨迹。须先 prepare_continue。 */
void helm_shell_continue_ride(float km, uint32_t sec, const float * lon,
                              const float * lat, uint16_t n);
/** @brief GNSS 回放跳里程：未开录则开录；已暂停则继续。 */
void helm_shell_ensure_ride(void);
/** @brief 导航开始：切到地图页。不自动开始录像。 */
void helm_shell_on_nav_started(void);
/** @brief 通栏导航横幅此刻是否可见（地图据此决定是否下移半个横幅高）。 */
bool helm_shell_nav_ban_shown(void);

/** @brief 演示：直接显示指定页面（UI 线程）。名字：ring/standby/ride/data/map/turn/climb。 */
bool helm_shell_demo_page(const char * name);

/**
 * @brief 演示：环形主页切到指定模式（**仅调试**，UI 线程）。
 * @param mode 0=骑行 1=导航 2=记录 3=设置；越界按 0..3 取模。
 * @details 直接摆到目标态（联动扇区/指针/盘心文案），不模拟按键、不播旋转动效。
 *          模拟器出四张模式图用；不参与板端业务流程。
 */
void helm_shell_demo_ring(int mode);

/**
 * @brief 演示：注入 KEY 页面回调（**仅调试**，模拟器用）。
 * @param key 1 = KEY1，2 = KEY2；其它值忽略。
 * @param long_press true = 长按回调，false = 短按回调。
 * @details 模拟器里 lv_port_buttons 整份被 `#if __NuttX__` 关掉，
 *          这里在**页面回调边界**直接调 `helm_shell_bind_keys()` 注册的那几个
 *          函数（不经过按键状态机的长按判定）。板端不要调用。
 */
void helm_shell_demo_key(int key, bool long_press);

/**
 * @brief 演示：打印环形主页的几何与文字墨迹（**仅调试**）。
 * @details 一行一个对象：`[ring] geo name=x1,y1,x2,y2`、`[ring] ink name=WxH`。
 *          布局断言脚本从 verify.log 里读这些行，模拟器与板端同一套坐标。
 */
void helm_shell_demo_ring_dump(void);
/** @brief 演示：清除页面锁，恢复正常轮转。 */
void helm_shell_demo_page_clear(void);
/** @brief 演示：强制导航横幅状态。0=off；1=直行,2=左转,3=偏航,4=到达,5=右转,6=掉头,7=重规划。 */
void helm_shell_demo_banner(int mode);
/** @brief 演示：显示/隐藏"保存"确认层。 */
void helm_shell_demo_save(bool on);

/**
 * @brief 演示/取证：保存两段卡的文案与键帽几何（**仅调试**）。
 * @details 一行一个对象：`[save]` = 第一段（询问卡），`[save2]` = 第二段
 *          （已保存/未保存结果卡）；键帽行给出 `left_cap/right_cap` 屏幕坐标、
