8393	static int helm_ring_norm(int a)
8394	{
8395	    a %= 360;
8396	    return (a < 0) ? (a + 360) : a;
8397	}
8398	
8399	/** @brief trig(±32767) × r，四舍五入（不用 libm，板端与模拟器同一算法）。 */
8400	static int helm_ring_trig(int32_t v, int r)
8401	{
8402	    int64_t p = (int64_t)v * r;
8403	
8404	    if (p >= 0) {
8405	        return (int)((p + 16384) / 32767);
8406	    }
8407	    return (int)((p - 16384) / 32767);
8408	}
