8410	/** @brief 角度（0 = 12 点，顺时针）→ 页面根坐标。 */
8411	static void helm_ring_pt(int angle, int r, int * x, int * y)
8412	{
8413	    int a = helm_ring_norm(angle);
8414	
8415	    *x = HELM_RING_CX + helm_ring_trig(lv_trigo_sin((int16_t)a), r);
8416	    *y = HELM_RING_CY - helm_ring_trig(lv_trigo_cos((int16_t)a), r);
8417	}
