8533	/** @brief 24 刻度：整点 3px（INK）、其余 1px（MUTE）。 */
8534	static void helm_ring_build_ticks(lv_obj_t * parent)
8535	{
8536	    int i;
8537	
8538	    for (i = 0; i < 24; i++) {
8539	        const int deg = i * 15;
8540	        const bool major = (i % 6) == 0;
8541	        const int th = major ? 3 : 1;
8542	        int x1, y1, x2, y2;
8543	        int x, y, w, h;
8544	        lv_obj_t * box;
8545	
8546	        helm_ring_pt(deg, major ? HELM_RING_TICK_RIN_M : HELM_RING_TICK_RIN_m,
8547	                     &x1, &y1);
8548	        helm_ring_pt(deg, HELM_RING_TICK_ROUT, &x2, &y2);
8549	        if (LV_ABS(x2 - x1) >= LV_ABS(y2 - y1)) {
8550	            x = (x1 < x2) ? x1 : x2;
8551	            y = y1;
8552	            w = LV_ABS(x2 - x1) + 1;
8553	            h = th;
8554	        } else {
8555	            x = x1;
8556	            y = (y1 < y2) ? y1 : y2;
8557	            w = th;
8558	            h = LV_ABS(y2 - y1) + 1;
8559	        }
8560	
8561	        box = lv_obj_create(parent);
8562	        lv_obj_remove_style_all(box);
8563	        lv_obj_set_pos(box, x, y);
8564	        lv_obj_set_size(box, w, h);
8565	        lv_obj_set_style_bg_color(box,
8566	            helm_color(major ? HELM_COLOR_INK : HELM_COLOR_MUTE), 0);
8567	        lv_obj_set_style_bg_opa(box, LV_OPA_COVER, 0);
8568	        lv_obj_set_style_radius(box, th / 2, 0);
8569	        lv_obj_remove_flag(box, LV_OBJ_FLAG_CLICKABLE);
8570	        lv_obj_clear_flag(box, LV_OBJ_FLAG_SCROLLABLE);
8571	        s_sh.ring_tick[i] = box;
8572	    }
8573	}
