8575	/** @brief 指针：中心 → r=72 的杆 + 末端 8px 横杆。 */
8576	static void helm_ring_pointer_layout(int32_t angle)
8577	{
8578	    const int a = helm_ring_norm((int)angle);
8579	    const int32_t sn = lv_trigo_sin((int16_t)a);
8580	    const int32_t cs = lv_trigo_cos((int16_t)a);
8581	    const int sx = (int)sn;
8582	    const int sy = (int)(-cs);
8583	    const int px = (int)cs;
8584	    const int py = (int)sn;
8585	    const int x0 = HELM_RING_CX + helm_ring_trig(sx, HELM_RING_PTR_R0);
8586	    const int y0 = HELM_RING_CY + helm_ring_trig(sy, HELM_RING_PTR_R0);
8587	    const int x1 = HELM_RING_CX + helm_ring_trig(sx, HELM_RING_PTR_R1);
8588	    const int y1 = HELM_RING_CY + helm_ring_trig(sy, HELM_RING_PTR_R1);
8589	
8590	    s_sh.ring_ptr_pts[0].x = x0;
8591	    s_sh.ring_ptr_pts[0].y = y0;
8592	    s_sh.ring_ptr_pts[1].x = x1;
8593	    s_sh.ring_ptr_pts[1].y = y1;
8594	    s_sh.ring_cross_pts[0].x =
8595	        x1 - helm_ring_trig(px, HELM_RING_PTR_CROSS);
8596	    s_sh.ring_cross_pts[0].y =
8597	        y1 - helm_ring_trig(py, HELM_RING_PTR_CROSS);
8598	    s_sh.ring_cross_pts[1].x =
8599	        x1 + helm_ring_trig(px, HELM_RING_PTR_CROSS);
8600	    s_sh.ring_cross_pts[1].y =
8601	        y1 + helm_ring_trig(py, HELM_RING_PTR_CROSS);
8602	    if (s_sh.ring_ptr != NULL) {
8603	        lv_line_set_points(s_sh.ring_ptr, s_sh.ring_ptr_pts, 2);
8604	    }
8605	    if (s_sh.ring_cross != NULL) {
8606	        lv_line_set_points(s_sh.ring_cross, s_sh.ring_cross_pts, 2);
8607	    }
8608	}
