8716	/** @brief 盘心数值 + 副行（每 500ms 刷新；只改文本与水平居中）。 */
8717	static void helm_ring_paint_values(const bicycle_runtime_t * rt)
8718	{
8719	    char v[24];
8720	    char u[8];
8721	    char sub[64];
8722	    char km[16];
8723	    bool has_unit = false;
8724	    const int mode = s_sh.ring_mode & 3;
8725	
8726	    v[0] = '\0';
8727	    u[0] = '\0';
8728	    sub[0] = '\0';
8729	
8730	    switch (mode) {
8731	    case 0:
8732	        /* 骑行：上次骑行里程（来源 = shell 既有的 last_km，即
8733	         * myvendor_devctl_last_ride_m_get / 保存骑行时回写）。 */
8734	        if (s_sh.last_km > 0.05f) {
8735	            helm_fmt_km(km, sizeof(km), s_sh.last_km);
8736	        } else {
8737	            lv_snprintf(km, sizeof(km), "0.0");
8738	        }
8739	        lv_snprintf(v, sizeof(v), "%s", km);
8740	        lv_snprintf(u, sizeof(u), "km");
8741	        has_unit = true;
8742	        if (helm_riding()) {
8743	            char sp[16];
8744	
8745	            helm_fmt_speed(sp, sizeof(sp), helm_session_avg_kph(rt));
8746	            lv_snprintf(sub, sizeof(sub), "均速 %s km/h", sp);
8747	        } else {
8748	            /* 描述行已经是「上次骑行」，副行再写一遍就是重复。 */
8749	            lv_snprintf(sub, sizeof(sub), "未开始骑行");
8750	        }
8751	        break;
8752	
8753	    case 1:
8754	        if (s_sh.map != NULL && map_page_nav_active(s_sh.map)) {
8755	            double rem = map_page_nav_remain_m(s_sh.map);
8756	            double tot = map_page_nav_total_m(s_sh.map);
8757	            char tk[16];
8758	
8759	            if (rem < 0.0) {
8760	                rem = 0.0;
8761	            }
8762	            if (tot < 0.0) {
8763	                tot = 0.0;
8764	            }
8765	            helm_fmt_km(km, sizeof(km), (float)(rem / 1000.0));
8766	            helm_fmt_km(tk, sizeof(tk), (float)(tot / 1000.0));
8767	            lv_snprintf(v, sizeof(v), "%s", km);
8768	            lv_snprintf(u, sizeof(u), "km");
8769	            has_unit = true;
8770	            lv_snprintf(sub, sizeof(sub), "全程 %s km", tk);
8771	        } else {
8772	            lv_snprintf(v, sizeof(v), "--");
8773	            lv_snprintf(sub, sizeof(sub), "未在导航");
8774	        }
8775	        break;
8776	
8777	    case 2:
8778	        /* 记录：拿不到 GPX 条数/最近日期 ⇒ 显示上次记录里程，副行"暂无"。 */
8779	        if (s_sh.last_km > 0.05f) {
