8785	        lv_snprintf(u, sizeof(u), "km");
8786	        has_unit = true;
8787	        lv_snprintf(sub, sizeof(sub), "暂无记录日期");
8788	        break;
8789	
8790	    default: {
8791	        int pct = myvendor_sys_battery_percent();
8792	        const char * ver = myvendor_sw_version();
8793	
8794	        if (pct < 0) {
8795	            pct = 0;
8796	        } else if (pct > 100) {
8797	            pct = 100;
8798	        }
8799	        lv_snprintf(v, sizeof(v), "%d", pct);
8800	        lv_snprintf(u, sizeof(u), "%%");
8801	        has_unit = true;
8802	        if (ver != NULL && ver[0] != '\0') {
8803	            lv_snprintf(sub, sizeof(sub), "固件 %s", ver);
8804	        } else {
8805	            lv_snprintf(sub, sizeof(sub), "固件 --");
8806	        }
8807	        break;
8808	    }
8809	    }
8810	
8811	    helm_label_set(s_sh.ring_value, v);
8812	    helm_set_text_hex(s_sh.ring_value, HELM_COLOR_INK);
8813	    helm_ring_value_layout(v, has_unit, u);
8814	    helm_label_set(s_sh.ring_sub, sub);
