8840	/**
8841	 * @brief 一次把扇区/指针/盘心落到目标模式（瞬时切换，无 lv_anim）。
8842	 * @details 用户实测板端整屏 10~15 fps，160 ms 交叉淡入就是"转起来很卡"；
8843	 *          改成同一帧内删旧扇区、建新扇区、摆指针、换盘心文字。
8844	 */
8845	static void helm_ring_apply(int mode)
8846	{
8847	    int i;
8848	
8849	    mode &= 3;
8850	
8851	    if (s_sh.ring == NULL) {
8852	        s_sh.ring_mode = (uint8_t)mode;
8853	        return;
8854	    }
8855	
8856	    for (i = 0; i < 2; i++) {
8857	        if (s_sh.ring_fill[i] != NULL) {
8858	            lv_obj_delete(s_sh.ring_fill[i]);
8859	            s_sh.ring_fill[i] = NULL;
8860	        }
8861	        if (s_sh.ring_trk[i] != NULL) {
8862	            lv_obj_delete(s_sh.ring_trk[i]);
8863	            s_sh.ring_trk[i] = NULL;
8864	        }
8865	    }
8866	
8867	    s_sh.ring_mode = (uint8_t)mode;
8868	    helm_ring_sector_make(mode);
8869	    s_sh.ring_angle = (int32_t)mode * 90;
8870	    helm_ring_pointer_layout(s_sh.ring_angle);
8871	    helm_ring_paint_mode(mode);
8872	    helm_ring_paint_values(bicycle_runtime_get());
8873	}
