8875	/** @brief 动画帧：只重摆指针（两条 lv_line），扇区/盘心不动。 */
8876	static void helm_ring_anim_exec(void * var, int32_t v)
8877	{
8878	    uint32_t now;
8879	
8880	    (void)var;
8881	    helm_ring_pointer_layout(v);
8882	
8883	    now = lv_tick_get();
8884	    if (s_ring_anim_frames != 0) {
8885	        uint32_t dt = now - s_ring_anim_last;
8886	
8887	        if (dt > s_ring_anim_maxdt) {
8888	            s_ring_anim_maxdt = dt;
8889	        }
8890	    }
8891	    s_ring_anim_last = now;
8892	    s_ring_anim_frames++;
8893	}
