8895	/** @brief 动画完成：扇区/盘心一次性落位，并打帧耗时供上板核对。 */
8896	static void helm_ring_anim_done(lv_anim_t * a)
8897	{
8898	    (void)a;
8899	    s_ring_anim_active = false;
8900	    helm_ring_apply((int)s_ring_anim_to);
8901	    printf("[ring] anim done mode=%u frames=%u maxdt=%ums\n",
8902	           (unsigned)s_ring_anim_to, (unsigned)s_ring_anim_frames,
8903	           (unsigned)s_ring_anim_maxdt);
8904	    s_ring_anim_last = 0;
8905	    s_ring_anim_maxdt = 0;
8906	    s_ring_anim_frames = 0;
