8909	/**
8910	 * @brief 环转一格（指针扫过去，落位时再换扇区/盘心）。
8911	 * @param dir +1 顺时针（KEY1 短，环形页下一个模式）、−1 逆时针。
8912	 */
8913	static void helm_ring_rotate(int dir)
8914	{
8915	    int from;
8916	    int to;
8917	    int32_t a0;
8918	    lv_anim_t a;
8919	
8920	    if (!s_sh.attached || s_sh.ring == NULL ||
8921	        s_sh.view_id != HELM_PAGE_RING) {
8922	        return;
8923	    }
8924	    if (dir == 0) {
8925	        dir = 1;
8926	    }
8927	
8928	    /* 上一段还没跑完：先按它的目标落位，再从落位角起转，避免角度叠错。 */
8929	    if (s_ring_anim_active) {
8930	        lv_anim_delete(&s_ring_anim_angle, helm_ring_anim_exec);
8931	        s_ring_anim_active = false;
8932	        helm_ring_apply((int)s_ring_anim_to);
8933	    }
8934	
8935	    from = s_sh.ring_mode & 3;
8936	    to = (from + ((dir > 0) ? 1 : 3)) & 3;
8937	    a0 = s_sh.ring_angle;
8938	    s_ring_anim_to = (uint8_t)to;
8939	    s_ring_anim_frames = 0;
8940	    s_ring_anim_last = lv_tick_get();
8941	    s_ring_anim_maxdt = 0;
8942	    s_ring_anim_active = true;
8943	
8944	    printf("[ring] anim mode=%d->%d a0=%d\n", from, to, (int)a0);
8945	
8946	    lv_anim_init(&a);
8947	    lv_anim_set_var(&a, &s_ring_anim_angle);
8948	    lv_anim_set_values(&a, a0, a0 + dir * 90);
8949	    lv_anim_set_duration(&a, HELM_RING_ANIM_MS);
8950	    lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
8951	    lv_anim_set_exec_cb(&a, helm_ring_anim_exec);
8952	    lv_anim_set_ready_cb(&a, helm_ring_anim_done);
8953	    lv_anim_start(&a);
8954	}
