bool myvendor_epic_rotate(const uint16_t *src_buf, uint32_t src_stride, int32_t src_w,
                          int32_t src_h, uint16_t *dst_buf, uint32_t dst_stride,
                          int32_t dst_w, int32_t dst_h, int32_t angle10, int32_t pivot_x,
                          int32_t pivot_y, int32_t dst_cx, int32_t dst_cy)
{
    /*
     * 软件最近邻旋转（WP-VMAPC/R1 加）：板端由 EPIC 做同一件事，PC 上没有
     * 硬件 ⇒ 以前直接返回 false，`vmap_rot_full()` 永远失败，航向朝上在
     * 模拟器里**一张图都出不来**（R 缓冲路径无法验证）。
     *
     * 语义照抄 `myvendor_epic_blit.c` 的 `myvendor_epic_rotate_impl()`：
     *   正向：dst = R(θ)·(src - pivot) + (dst_cx, dst_cy)，θ = angle10/10 度，
     *         **顺时针**（屏幕坐标 y 向下）；最近邻、无插值；
     *   背景 = 目的层本身（旋转层之外保持原像素，不清零）。
     * 只用于模拟器取证，性能与 EPIC 无关（不要拿它当性能数字）。
     */
    const double th = (double)angle10 * 0.1 * M_PI / 180.0;
    const double c = cos(th);
    const double s = sin(th);
    int32_t x;
    int32_t y;

    if (src_w <= 0 || src_h <= 0 || dst_w <= 0 || dst_h <= 0
        || angle10 < 0 || angle10 >= 3600) {
        return false;
    }

    for (y = 0; y < dst_h; y++) {
        uint16_t *drow = (uint16_t *)((uint8_t *)dst_buf + (size_t)y * dst_stride);
        const double dy = (double)y - (double)dst_cy;

        for (x = 0; x < dst_w; x++) {
            const double dx = (double)x - (double)dst_cx;
            /* 逆向映射：dst 绕 (dst_cx,dst_cy) 转 -θ 再搬到 pivot。 */
            const double fx = c * dx + s * dy + (double)pivot_x;
            const double fy = -s * dx + c * dy + (double)pivot_y;
            const int32_t sx = (int32_t)lround(fx);
            const int32_t sy = (int32_t)lround(fy);

            if (sx < 0 || sy < 0 || sx >= src_w || sy >= src_h) {
                continue;
            }
            drow[x] = *(const uint16_t *)((const uint8_t *)src_buf
                + (size_t)sy * src_stride + (size_t)sx * sizeof(uint16_t));
        }
    }
    return true;
}

