 * 模拟器取证用它跑一次，`SIM_EPIC_READY=0`（或不设）就是"强制 EPIC 不可用"
 * 的回退用例。
 * ══════════════════════════════════════════════════════════════════════════ */

static bool sim_epic_ready_cached(void)
{
    static int cached = -1;

    if (cached < 0) {
        const char *env = getenv("SIM_EPIC_READY");

        cached = (env != NULL && env[0] == '1') ? 1 : 0;
    }
    return cached == 1;
}

bool myvendor_epic_ready(void)
{
    return sim_epic_ready_cached();
}

bool myvendor_epic_busy(void)
{
    return false;
}

bool myvendor_epic_copy(uint16_t *dst_buf, uint32_t dst_stride, int32_t dx, int32_t dy,
                        const uint16_t *src_buf, uint32_t src_stride, int32_t sx, int32_t sy,
                        int32_t w, int32_t h)
{
    int32_t y;

    if (!sim_epic_ready_cached() || dst_buf == NULL || src_buf == NULL ||
        w <= 0 || h <= 0 || dx < 0 || dy < 0 || sx < 0 || sy < 0) {
        return false;
    }
    for (y = 0; y < h; y++) {
        memmove((uint8_t *)dst_buf + (size_t)(dy + y) * dst_stride +
                    (size_t)dx * sizeof(uint16_t),
                (const uint8_t *)src_buf + (size_t)(sy + y) * src_stride +
                    (size_t)sx * sizeof(uint16_t),
                (size_t)w * sizeof(uint16_t));
    }
    return true;
}

bool myvendor_epic_fill(uint16_t *dst_buf, uint32_t dst_stride, int32_t x, int32_t y,
                        int32_t w, int32_t h, uint16_t color565)
{
    int32_t j;

    if (!sim_epic_ready_cached() || dst_buf == NULL || w <= 0 || h <= 0 ||
