        return false;
    }
    for (j = 0; j < h; j++) {
        uint16_t *row = (uint16_t *)((uint8_t *)dst_buf +
                                     (size_t)(y + j) * dst_stride);

        for (int32_t i = 0; i < w; i++) {
            row[x + i] = color565;
        }
    }
    return true;
